#!/usr/bin/env node
/**
 * Build a verified `co-arising.explorer-snapshot/v1` bundle for `/explorer/` and `/zh/explorer/`
 * directly from `bank-wealth-demo/v2-pilot/` (generated by `scala-cqrs-play-service:2` + TypeScript)
 * and activate `assets/data/explorer/current.json`.
 *
 * Keeps historical snapshots untouched under `assets/data/explorer/snapshots/`.
 */
import assert from 'node:assert/strict';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { DatabaseSync } from 'node:sqlite';
import {
  INDEX_SCHEMA,
  SCHEMA,
  descriptor,
  publicSnapshotId,
  validateSnapshotBundle,
} from './explorer-snapshot-contract.mjs';
import {
  jsonBytes,
  safePath,
  sensitiveReason,
  sha256,
  verifySpan,
} from './explorer-snapshot-security.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SITE_ROOT = resolve(__dirname, '..');

function parseArgs(argv) {
  const opts = {
    bank: resolve(SITE_ROOT, '..', 'bank-wealth-demo'),
    truthsrc: resolve(SITE_ROOT, '..', 'metarch-truthsrc'),
    outBase: resolve(SITE_ROOT, 'assets', 'data', 'explorer'),
    activate: true,
  };
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i] === '--bank' && argv[i + 1]) opts.bank = resolve(argv[++i]);
    else if (argv[i] === '--truthsrc' && argv[i + 1]) opts.truthsrc = resolve(argv[++i]);
    else if (argv[i] === '--out-base' && argv[i + 1]) opts.outBase = resolve(argv[++i]);
    else if (argv[i] === '--no-activate') opts.activate = false;
  }
  return opts;
}

function escapeJsonPointerSegment(seg) {
  return String(seg).replace(/~/gu, '~0').replace(/\//gu, '~1');
}

function lineRangeToUtf8ByteSpan(buf, startLine, endLine) {
  const text = buf.toString('utf8');
  const lines = text.split('\n');
  const clampedStart = Math.max(1, Math.min(startLine, lines.length));
  const clampedEnd = Math.max(clampedStart, Math.min(endLine, lines.length));
  let startByte = 0;
  for (let i = 0; i < clampedStart - 1; i += 1) {
    startByte += Buffer.byteLength(lines[i], 'utf8') + 1;
  }
  let endByte = startByte;
  for (let i = clampedStart - 1; i < clampedEnd; i += 1) {
    endByte += Buffer.byteLength(lines[i], 'utf8');
    if (i < clampedEnd - 1) endByte += 1;
  }
  if (endByte <= startByte && endByte < buf.length) {
    endByte = Math.min(buf.length, startByte + 1);
  }
  if (endByte <= startByte) return null;
  return { start: startByte, end: endByte };
}

function buildExplorerSqliteBytes(v2DbPath, canonicalSha256, verifiedAt) {
  const srcDb = new DatabaseSync(v2DbPath, { readOnly: true });
  const metaRows = srcDb.prepare('SELECT key, value FROM metadata ORDER BY key').all();
  const nodeRows = srcDb.prepare('SELECT id, kind, name, layer, payload FROM nodes ORDER BY id').all();
  const edgeRows = srcDb.prepare('SELECT from_id, to_id, relation FROM edges ORDER BY from_id, relation, to_id').all();
  srcDb.close();

  const tmpDir = mkdtempSync(join(tmpdir(), 'explorer-v2-sqlite-'));
  const tmpSqlite = join(tmpDir, 'graph.sqlite');
  try {
    const outDb = new DatabaseSync(tmpSqlite);
    outDb.exec(`
      CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
      CREATE TABLE nodes (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, atom TEXT NOT NULL, extra TEXT);
      CREATE TABLE edges (seq INTEGER PRIMARY KEY, from_id TEXT NOT NULL, relation TEXT NOT NULL, to_id TEXT NOT NULL);
      CREATE INDEX edges_from ON edges(from_id);
      CREATE INDEX edges_to ON edges(to_id);
    `);

    const insMeta = outDb.prepare('INSERT INTO meta(key, value) VALUES (?, ?)');
    const seenMeta = new Set();
    for (const r of metaRows) {
      const val = String(r.value ?? '').replace(/\/Users\/[^\s"'<>]+/gu, '[redacted]');
      insMeta.run(r.key, val);
      seenMeta.add(r.key);
    }
    if (!seenMeta.has('generator')) insMeta.run('generator', 'scala-cqrs-play-service:2');
    if (!seenMeta.has('canonicalSha256')) insMeta.run('canonicalSha256', canonicalSha256);
    if (!seenMeta.has('exportedAt')) insMeta.run('exportedAt', verifiedAt);

    const insNode = outDb.prepare('INSERT INTO nodes(id, kind, name, atom, extra) VALUES (?, ?, ?, ?, ?)');
    for (const r of nodeRows) {
      let payloadObj = {};
      try { payloadObj = JSON.parse(r.payload || '{}'); } catch { payloadObj = {}; }
      const atom = JSON.stringify({
        id: r.id,
        kind: r.kind,
        name: r.name,
        layer: r.layer || 'domain',
        ...payloadObj,
        provenance: {
          sourceVersion: 'co-arising-2.0.0',
          sourceArtifact: 'scala-cqrs-play-service:2',
        },
      }).replace(/\/Users\/[^\s"'<>]+/gu, '[redacted]');
      const extra = JSON.stringify({ layer: r.layer || 'domain' });
      insNode.run(r.id, r.kind, r.name, atom, extra);
    }

    const insEdge = outDb.prepare('INSERT INTO edges(seq, from_id, relation, to_id) VALUES (?, ?, ?, ?)');
    edgeRows.forEach((e, idx) => {
      insEdge.run(idx + 1, e.from_id, e.relation, e.to_id);
    });
    outDb.close();
    return {
      graphBytes: readFileSync(tmpSqlite),
      nodeCount: nodeRows.length,
      edgeCount: edgeRows.length,
    };
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const v2Root = join(opts.bank, 'v2-pilot');
  const v2DbPath = join(v2Root, '.truthsrc', 'knowledge.sqlite');
  const provPath = join(v2Root, '.truthsrc', 'v2-provenance.json');
  assert.ok(existsSync(v2DbPath), `missing v2 SQLite DB: ${v2DbPath}`);
  assert.ok(existsSync(provPath), `missing v2 provenance JSON: ${provPath}`);

  const provenance = JSON.parse(readFileSync(provPath, 'utf8'));
  assert.equal(provenance.passed, true, 'v2-pilot verify-v2 provenance must be passed=true before publishing explorer snapshot');

  const { buildV2WorkshopView } = await import(pathToFileURL(join(opts.truthsrc, 'lib', 'v2', 'view-v2.mjs')).href);
  const view = buildV2WorkshopView({
    rootDir: v2Root,
    dbFile: v2DbPath,
    pathPrefix: '',
  });

  const verifiedAt = provenance.verifiedAt || new Date().toISOString();
  const canonicalDigest = view.snapshot.generation.startsWith('canonical:')
    ? `sha256:${view.snapshot.generation.slice('canonical:'.length)}`
    : view.snapshot.generation;

  const { graphBytes, nodeCount, edgeCount } = buildExplorerSqliteBytes(v2DbPath, canonicalDigest, verifiedAt);

  // Build file catalog (author / generated / handwritten)
  const files = [];
  const fileByPath = new Map();
  const fileBuffers = new Map();

  for (const f of view.verification.files) {
    const rel = f.file;
    assert.ok(safePath(rel), `unsafe path: ${rel}`);
    const role = rel.startsWith('truth/')
      ? 'author'
      : rel.startsWith('handwritten/')
        ? 'handwritten'
        : 'generated';
    const abs = join(v2Root, rel);
    const bytes = readFileSync(abs);
    const digest = sha256(bytes);
    const id = `file:${sha256(Buffer.from(`${role}:${rel}`))}`;
    const reason = sensitiveReason(bytes.toString('utf8'), [], { sourcePath: rel });
    const row = {
      id,
      path: rel,
      role,
      sha256: digest,
      bytes: bytes.length,
      state: reason ? 'withheld' : 'published',
      ...(reason ? { reason } : { resource: descriptor(`files/${digest}.txt`, bytes) }),
    };
    files.push(row);
    fileByPath.set(rel, row);
    fileBuffers.set(id, bytes);
  }
  files.sort((a, b) => a.id.localeCompare(b.id));

  const edgeRelationsByFrom = new Map();
  for (const e of view.edges) {
    if (!edgeRelationsByFrom.has(e.from)) edgeRelationsByFrom.set(e.from, []);
    edgeRelationsByFrom.get(e.from).push({ identity: e.to, carrier: e.label });
  }

  const nodes = [];
  const identities = [];
  const locations = [];
  const seenLocIds = new Set();

  for (const n of view.nodes) {
    const ptr = `/${escapeJsonPointerSegment(n.kind)}/${escapeJsonPointerSegment(n.label)}`;
    nodes.push({
      id: n.id,
      state: 'mapped',
      identities: [n.id],
      pointers: [ptr],
    });

    const sources = [];
    for (const s of n.sources ?? []) {
      const fRow = fileByPath.get(s.file);
      if (!fRow || fRow.role !== 'author') continue;
      const lineCount = fileBuffers.get(fRow.id).toString('utf8').split('\n').length;
      const startLine = Math.max(1, Math.min(s.startLine ?? 1, lineCount));
      const endLine = Math.max(startLine, Math.min(s.endLine ?? startLine, lineCount));
      const srcPtr = `/${String(s.pointer || n.id).split('/').map(escapeJsonPointerSegment).join('/')}`;
      sources.push({
        fileId: fRow.id,
        pointer: srcPtr,
        pointerLocated: true,
        startLine,
        endLine,
      });
    }

    const rels = (edgeRelationsByFrom.get(n.id) ?? []).filter(r => view.nodes.some(x => x.id === r.identity));
    identities.push({
      id: n.id,
      name: n.label,
      kind: n.kind,
      graphNodeIds: [n.id],
      sources,
      ...(rels.length > 0 ? { relations: rels } : {}),
    });

    for (let ord = 0; ord < (n.locations ?? []).length; ord += 1) {
      const loc = n.locations[ord];
      const fRow = fileByPath.get(loc.file);
      if (!fRow || fRow.role !== 'generated') continue;
      const buf = fileBuffers.get(fRow.id);
      const startLine = loc.highlight?.startLine ?? loc.startLine ?? 1;
      const endLine = loc.highlight?.endLine ?? loc.endLine ?? startLine;
      const byteSpan = lineRangeToUtf8ByteSpan(buf, startLine, endLine);
      if (byteSpan) {
        verifySpan(buf, byteSpan);
      }
      const knowledgeKey = `source:${n.id}`;
      const locId = `location:${sha256(Buffer.from(JSON.stringify([knowledgeKey, ord, n.id, fRow.id, byteSpan?.start ?? null, byteSpan?.end ?? null])))}`;
      if (seenLocIds.has(locId)) continue;
      seenLocIds.add(locId);
      locations.push({
        id: locId,
        identity: n.id,
        fileId: fRow.id,
        precision: byteSpan ? 'span' : 'file',
        knowledgeKey,
        ...(byteSpan ? { span: byteSpan } : {}),
      });
    }
  }

  nodes.sort((a, b) => a.id.localeCompare(b.id));
  identities.sort((a, b) => a.id.localeCompare(b.id));
  locations.sort((a, b) => a.id.localeCompare(b.id));

  const index = {
    schemaVersion: INDEX_SCHEMA,
    snapshot: '',
    nodes,
    files,
    identities,
    locations,
  };

  const exporterFingerprint = sha256(readFileSync(fileURLToPath(import.meta.url)));
  const toolFingerprint = sha256(readFileSync(join(opts.truthsrc, 'generators', 'scala-cqrs-play-service-v2', 'generate.mjs')));
  const tsSuites = provenance.tsCheck?.specFiles?.length ?? 0;
  const scalaSuites = provenance.scalaCheck?.suiteClasses?.length ?? 0;
  const manifest = {
    schemaVersion: SCHEMA,
    id: '',
    project: { name: 'bank-wealth-v2 (scala-cqrs-play-service:2)' },
    verifiedAt,
    graph: {
      ...descriptor('graph.sqlite', graphBytes),
      nodeCount,
      edgeCount,
      canonicalDigest,
    },
    index: descriptor('index.json', jsonBytes(index)),
    counts: {
      files: files.length,
      publishedFiles: files.filter(f => f.state === 'published').length,
      withheldFiles: files.filter(f => f.state === 'withheld').length,
      identities: identities.length,
      locations: locations.length,
      spanLocations: locations.filter(l => l.precision === 'span').length,
      mappedNodes: nodes.filter(n => n.identities.length > 0).length,
    },
    evidence: {
      state: 'verified-at-export',
      runtime: 'compile-and-test-passed',
      runtimeEvidence: {
        command: 'truthsrc verify-v2 --target typescript,scala-cqrs-play-service-v2 --strict --mutation-gate',
        compiledSources: files.filter(f => f.path.endsWith('.scala') || f.path.endsWith('.ts')).length,
        suitesPassed: tsSuites + scalaSuites,
        testsPassed: (provenance.mutationCheck?.ts?.killed ?? 0) + (provenance.mutationCheck?.scala?.killed ?? 0) + (provenance.manifestCheck?.verifiedFiles ?? 0),
        verifiedAt,
      },
      sourceSnapshot: view.snapshot.source,
      knowledgeSnapshot: view.snapshot.knowledge,
      generation: canonicalDigest,
      codeDigest: view.snapshot.codeDigest,
      toolFingerprint,
      exporterFingerprint,
    },
  };

  const snapId = publicSnapshotId(manifest, index);
  manifest.id = snapId;
  index.snapshot = snapId;
  manifest.index = descriptor('index.json', jsonBytes(index));

  // Fail-closed contract verification before writing to disk
  const validatedCounts = validateSnapshotBundle({ manifest, index, graphBytes, fileBuffers });

  const snapDir = join(opts.outBase, 'snapshots', snapId);
  const filesDir = join(snapDir, 'files');
  mkdirSync(filesDir, { recursive: true });
  writeFileSync(join(snapDir, 'graph.sqlite'), graphBytes);
  for (const f of files) {
    if (f.state === 'published') {
      writeFileSync(join(filesDir, `${f.sha256}.txt`), fileBuffers.get(f.id));
    }
  }
  const indexBuf = jsonBytes(index);
  const manifestBuf = jsonBytes(manifest);
  writeFileSync(join(snapDir, 'index.json'), indexBuf);
  writeFileSync(join(snapDir, 'manifest.json'), manifestBuf);

  if (opts.activate) {
    const current = {
      schemaVersion: 'co-arising.explorer-current/v1',
      state: 'available',
      snapshot: snapId,
      manifest: {
        path: `snapshots/${snapId}/manifest.json`,
        bytes: manifestBuf.length,
        sha256: sha256(manifestBuf),
      },
    };
    writeFileSync(join(opts.outBase, 'current.json'), JSON.stringify(current, null, 2) + '\n', 'utf8');
  }

  console.log(JSON.stringify({
    snapshotId: snapId,
    activated: opts.activate,
    outDir: relative(SITE_ROOT, snapDir),
    nodeCount,
    edgeCount,
    counts: validatedCounts,
    manifestBytes: manifestBuf.length,
    indexBytes: indexBuf.length,
  }, null, 2));
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
